def max_sum(arr):
    """
    Returns the maximum sum of a bitonic subsequence in the given array.

    :param arr: List[int] - The input array of integers.
    :return: int - The maximum sum of a bitonic subsequence.
    """
    n = len(arr)
    if n == 0:
        return 0

    lis = [0] * n
    lds = [0] * n

    for i in range(n):
        lis[i] = arr[i]
        for j in range(i):
            if arr[i] > arr[j] and lis[i] < lis[j] + arr[i]:
                lis[i] = lis[j] + arr[i]

    for i in range(n - 1, -1, -1):
        lds[i] = arr[i]
        for j in range(i + 1, n):
            if arr[i] > arr[j] and lds[i] < lds[j] + arr[i]:
                lds[i] = lds[j] + arr[i]

    max_bitonic_sum = 0
    for i in range(n):
        max_bitonic_sum = max(max_bitonic_sum, lis[i] + lds[i] - arr[i])

    return max_bitonic_sum
